<script setup lang="ts">import {onMounted,reactive,ref} from 'vue';import {harnessApi} from '../runtime-client/api';import type {AppDescriptor} from '../types';const emit=defineEmits<{open:[string]}>();const rows=ref<AppDescriptor[]>([]);const error=ref('');const form=reactive({appKey:'',name:'',description:'',routeTitle:'',icon:'component',orderNum:0});const load=async()=>{try{rows.value=await harnessApi.listApps()}catch(e:any){error.value=e.message}};const create=async()=>{await harnessApi.createApp(form);Object.assign(form,{appKey:'',name:'',description:'',routeTitle:'',icon:'component',orderNum:0});await load()};const toggle=async(a:AppDescriptor)=>{await harnessApi.setEnabled(a.appKey,!a.enabled);await load()};onMounted(load);</script>
<template><main class="harness-admin"><h1>Harness Applications</h1><p v-if="error" role="alert">{{error}}</p><form @submit.prevent="create" class="harness-admin-form"><input v-model="form.appKey" required placeholder="app-key"><input v-model="form.name" required placeholder="Name"><input v-model="form.routeTitle" required placeholder="Route title"><button>Create application</button></form><table><thead><tr><th>Key</th><th>Name</th><th>Status</th><th>Published</th><th></th></tr></thead><tbody><tr v-for="app in rows" :key="app.id"><td><button class="link" @click="emit('open',app.appKey)">{{app.appKey}}</button></td><td>{{app.name}}</td><td>{{app.enabled?'Enabled':'Disabled'}}</td><td>{{app.publishedVersionId||'—'}}</td><td><button @click="toggle(app)">{{app.enabled?'Disable':'Enable'}}</button></td></tr></tbody></table></main></template>
